79	  String get xcodeSelectPath {
80	    if (_xcodeSelectPath == null) {
81	      try {
82	        _xcodeSelectPath = _processUtils.runSync(
83	          <String>['/usr/bin/xcode-select', '--print-path'],
84	        ).stdout.trim();
85	      } on ProcessException {
86	        // Ignored, return null below.
87	      } on ArgumentError {
