111	      try {
112	        final RunResult result = _processUtils.runSync(
113	          <String>['/usr/bin/xcrun', 'clang'],
114	        );
115	        if (result.stdout != null && result.stdout.contains('license')) {
116	          _eulaSigned = false;
117	        } else if (result.stderr != null && result.stderr.contains('license')) {
118	          _eulaSigned = false;
119	        } else {
120	          _eulaSigned = true;
121	        }
122	      } on ProcessException {
123	        _eulaSigned = false;
124	      }
125	    }
126	    return _eulaSigned;
127	  }
