148	  bool get isVersionSatisfactory {
149	    if (!_xcodeProjectInterpreter.isInstalled) {
150	      return false;
151	    }
152	    if (majorVersion > kXcodeRequiredVersionMajor) {
153	      return true;
154	    }
155	    if (majorVersion == kXcodeRequiredVersionMajor) {
156	      if (minorVersion == kXcodeRequiredVersionMinor) {
157	        return patchVersion >= kXcodeRequiredVersionPatch;
158	      }
159	      return minorVersion >= kXcodeRequiredVersionMinor;
160	    }
161	    return false;
162	  }
